for (const domain of Object.values(RELEASE_SOURCE_DOMAINS)) {
  domain.inverses.forEach(Object.freeze);
  Object.freeze(domain.inverses);
  Object.freeze(domain);
}

export function assertReleaseSourceTransfer(file, input) {
  assert(Object.hasOwn(RELEASE_SOURCE_DOMAINS, file), 'Unknown release source domain: ' + file);
  assert.equal(typeof input, 'string', 'Release source must be text: ' + file);
  assert(uniform(input), 'Mixed release source line endings: ' + file);
  const domain = RELEASE_SOURCE_DOMAINS[file], text = lf(input);
  assert.equal(hash(text), domain.currentSha256, 'Release complete current source drift: ' + file);
  assert.equal(blob(text), domain.currentBlob, 'Release complete current blob drift: ' + file);
  let baselineText = text;
  for (const hunk of domain.inverses) {
    assert(hunk.current.length, 'Empty release inverse context');
    assert.equal(baselineText.split(hunk.current).length - 1, 1, 'Missing/duplicate/reordered release inverse context: ' + file);
    baselineText = baselineText.replace(hunk.current, () => hunk.baseline);
  }
  assert.equal(hash(baselineText), domain.baselineSha256, 'Release complete predecessor source mismatch: ' + file);
  assert.equal(blob(baselineText), domain.baselineBlob, 'Release complete predecessor blob mismatch: ' + file);
  return { file, baselineText, sourceRevision: RELEASE_SOURCE_REVISION, predecessorRevision: RELEASE_SOURCE_PREDECESSOR,
    inverseChunks: domain.inverses.length, phase: RELEASE_SOURCE_PHASE, sourceOnly: true };
}

// No runtime discovery or pin refresh: only the literal candidate bytes above have an alias.
export function releaseSourceBaseline(file, input) {
  input = economyReleaseSource('main', file, input);
  if (!Object.hasOwn(RELEASE_SOURCE_DOMAINS, file) || typeof input !== 'string' || !uniform(input)) return input;
  return hash(lf(input)) === RELEASE_SOURCE_DOMAINS[file].currentSha256
    ? assertReleaseSourceTransfer(file, input).baselineText : input;
}
